"""Авторский контент C17. Генератор пишет только тексты, C запускается отдельно в Docker."""
import json
from pathlib import Path
ROOT=Path('content/cpp-systems')
items=[]
def add(slug,title,theory,model,mistake,task,code,cases,question,answer,wrong):
    items.append(dict(slug=slug,title=title,theory=theory,model=model,mistake=mistake,task=task,code=code.strip()+'\n',cases=cases,question=question,answer=answer,wrong=wrong))
def program(body,extra=''):
    return '#include <stdio.h>\n'+extra+'\nint main(void) {\n'+body+'\n    return 0;\n}\n'
add('translation-units','Translation units',
'''Единица трансляции — исходный файл после обработки директив препроцессора и включения заголовков. Компилятор проверяет её независимо от соседних .c. Поэтому объявление функции должно быть доступно в месте вызова: наличие реализации в другом файле не сообщает компилятору её тип. Объявление описывает интерфейс, определение предоставляет тело. Затем линкер связывает внешние ссылки объектных файлов.

Разделение позволяет пересобирать только затронутые части. Но граница файла не является границей безопасности типов всей программы: несовместимые объявления в разных единицах трансляции могут не вызвать понятной ошибки линкера. Один общий заголовок, включённый и клиентом, и реализацией, уменьшает этот риск. Не включайте .c вместо заголовка: это копирует определения и разрушает независимую сборку.''',
'Представьте отдельные цеха: каждый выпускает объектный файл по известным интерфейсам; линкер соединяет их внешние имена.',
'Вызов без прототипа недопустим в современном C. Подключение реализации через #include может дать несколько определений.',
'Прочитайте целую температуру от −100 до 100. Объявите функцию int calibrate(int), определите её после main; выведите температуру с поправкой +3.',
program('    int value;\n    if (scanf("%d", &value) != 1) return 1;\n    printf("%d\\n", calibrate(value));','int calibrate(int value);')+'\nint calibrate(int value) { return value + 3; }\n',
[('20\n','23\n'),('-100\n','-97\n'),('0\n','3\n')], 'Что компилятор должен знать в месте вызова?','Совместимый прототип функции','Только имя объектного файла')
add('headers','Header files',
'''Заголовок — текстовый контракт модуля. В нём размещают прототипы, типы и необходимые константы; определения общих объектов обычно остаются в .c. Заголовок должен быть самодостаточным: если интерфейс использует size_t, он сам включает stddef.h. Тогда порядок чужих include не меняет работоспособность клиента.

Реализация тоже включает свой заголовок. Это заставляет компилятор сопоставить объявление с определением. Минимизируйте зависимости: каждый лишний include увеличивает объём повторной обработки и связывает клиентов с деталями. Публичный struct раскрывает представление; непрозрачный тип скрывает поля, но требует отдельного API создания и уничтожения. Выбор определяется тем, кто управляет временем жизни объекта.''',
'Заголовок похож на разъём: клиенту нужны форма контактов и правила использования, а не внутренние провода.',
'Определение int counter = 0 в заголовке создаёт отдельное внешнее определение в каждом клиенте.',
'Опишите тип Sample с полями int value и int offset. Функция corrected принимает Sample и возвращает сумму. Ввод — два числа −1000…1000; вывод — исправленное измерение.',
program('    Sample s;\n    if (scanf("%d%d", &s.value, &s.offset) != 2) return 1;\n    printf("%d\\n", corrected(s));', 'typedef struct { int value; int offset; } Sample;\nstatic int corrected(Sample s) { return s.value + s.offset; }'),
[('12 -2','10\n'),('0 0','0\n'),('-100 30','-70\n')], 'Почему реализация включает свой заголовок?','Чтобы проверить согласованность объявления и определения','Чтобы линкер автоматически нашёл все файлы')
add('header-guards','Header guards',
'''Повторное текстовое включение заголовка может повторно определить struct или enum. Guard использует уникальный макрос: при первом включении #ifndef пропускает тело и #define отмечает его; следующие включения в той же единице трансляции пропускают тело. Между разными компиляциями состояние макроса не сохраняется.

Имя guard должно различаться у разных заголовков. Используйте префикс проекта и путь, например SENSOR_SAMPLE_H. Зарезервированные имена с двойным подчёркиванием оставьте реализации. Guard предотвращает повтор внутри единицы трансляции, но не исправляет внешнее определение переменной, попавшее в несколько .c. Для такой переменной нужен extern в заголовке и одно определение в реализации.''',
'На каждой сборочной площадке стоит свой штамп «уже прочитано»; штамп не является общим для всего проекта.',
'Скопированный guard с тем же именем может молча скрыть другой заголовок.',
'Защитите определение enum Channel guard-макросом SENSOR_CHANNEL_H. Прочитайте канал 0…2 и выведите размер пакета: 2, 4 или 8 байт.',
program('    int channel;\n    if (scanf("%d", &channel) != 1 || channel < 0 || channel > 2) return 1;\n    const int sizes[] = {2,4,8};\n    printf("%d\\n", sizes[channel]);','#ifndef SENSOR_CHANNEL_H\n#define SENSOR_CHANNEL_H\nenum Channel { TEMPERATURE, PRESSURE, POSITION };\n#endif'),
[('0','2\n'),('1','4\n'),('2','8\n')], 'Где действует состояние guard?','В одной единице трансляции','Сразу во всех объектных файлах')
add('preprocessor','Preprocessor',
'''Препроцессор работает с токенами до обычного анализа типов. Он включает файлы, раскрывает макросы и выбирает условные ветви. Он не знает значений переменных времени выполнения. После его работы компилятор видит уже преобразованный текст, поэтому сообщение об ошибке макроса удобнее исследовать через результат gcc -E.

Разделяйте причины: синтаксическая ошибка в раскрытии относится к компиляции; отсутствие определения внешнего имени проявится позже. Директивы не являются инструкциями процессора. Например #if выбирает один вариант программы при сборке, а if выбирает ветвь для каждого конкретного ввода. Конфигурация сборки должна воспроизводиться явно, а не зависеть от случайного набора макросов окружения.''',
'Это редактор рецепта до приготовления: после редактирования повар получает один окончательный рецепт.',
'Нельзя проверять runtime-переменную директивой #if; неизвестный идентификатор в её выражении обычно становится нулём.',
'Задайте SENSOR_GAIN равным 4 через макрос. Ввод x от −1000 до 1000. Выведите x * SENSOR_GAIN.',
program('    int x;\n    if (scanf("%d", &x) != 1) return 1;\n    printf("%d\\n", x * SENSOR_GAIN);','#define SENSOR_GAIN 4'),
[('7','28\n'),('-3','-12\n'),('0','0\n')], 'Когда раскрывается макрос?','До анализа типов компилятором','После выполнения main')
add('define','#define',
'''Объектоподобный макрос заменяет имя последовательностью токенов. Типизированного объекта и адреса у него нет. Скобки вокруг выражения сохраняют ожидаемый приоритет при подстановке. Не ставьте точку с запятой в значение: это внедряет лишнюю границу оператора в чужое выражение.

Для значения, которому нужен адрес или контроль типа, предпочтителен const-объект. Для целочисленной константы времени компиляции часто подходит enum. Макрос оправдан для препроцессорной конфигурации и условной компиляции. Например размер таблицы может зависеть от фиксированного числа каналов, но проверка диапазона пользовательского индекса всё равно выполняется во время работы.''',
'Макрос — текстовая подстановка, а не ячейка памяти с постоянным значением.',
'#define SCALE 2 + 3 превращает x * SCALE в x * 2 + 3.',
'Исправьте константу SENSOR_SCALE как (2 + 3). Прочитайте x от −100 до 100, выведите произведение.',
program('    int x;\n    if (scanf("%d", &x) != 1) return 1;\n    printf("%d\\n", x * SENSOR_SCALE);','#define SENSOR_SCALE (2 + 3)'),
[('4','20\n'),('-2','-10\n'),('0','0\n')], 'Чего нет у макроса-константы?','Собственного адреса объекта','Последовательности заменяющих токенов')
add('function-macros','Function-like macros',
'''Функциональноподобный макрос распознаётся по скобкам непосредственно после имени в определении. Параметры заменяются токенами аргументов. Скобки вокруг каждого аргумента и всего выражения защищают приоритет, но не предотвращают повторное вычисление. SQUARE(x) с двумя употреблениями x дважды подставляет выражение аргумента.

Обычная функция вычисляет каждый аргумент один раз до входа в тело. Поэтому арифметическую операцию с известным типом лучше выразить static inline функцией. Макрос полезен там, где требуется обработка токенов, например строкификация # или склейка ##. Это отдельный уровень абстракции, и его не следует смешивать с обычными вычислениями без необходимости.''',
'Макрос копирует написанное выражение; функция получает уже вычисленное значение.',
'Даже ((x)*(x)) опасен для SQUARE(i++): скобки не задают последовательность побочных эффектов.',
'Напишите безопасный макрос SENSOR_SQUARE и вызывайте его только с переменной без побочных эффектов. Ввод −100…100, вывод квадрат.',
program('    int x;\n    if (scanf("%d", &x) != 1) return 1;\n    printf("%d\\n", SENSOR_SQUARE(x));','#define SENSOR_SQUARE(x) ((x) * (x))'),
[('-7','49\n'),('0','0\n'),('100','10000\n')], 'Что решают скобки вокруг аргумента?','Приоритет операторов','Повторное вычисление побочных эффектов')
add('macro-hazards','Опасности макросов',
'''У макроса нет обычной области видимости локальных переменных функции. Он может захватить имя вызывающего кода, повторить аргумент или изменить структуру if/else. Многооператорный макрос оборачивают в do { ... } while (0), чтобы снаружи он выглядел как один оператор. Это не устраняет опасности повторного использования аргумента.

Сначала раскройте подозрительный вызов на бумаге, затем проверьте последовательность чтений и изменений. Не пытайтесь угадывать результат неопределённого поведения. Если операция вычисляет число, замена на inline-функцию обычно проще доказательства безопасности макроса. Инкремент лучше вынести в отдельный оператор: намерение становится проверяемым без знания реализации вспомогательной операции.''',
'Проверяйте результат копирования целиком, как будто вставили его руками в место вызова.',
'Выражения MIN(next(), limit) и SQUARE(i++) могут вызвать вычисление больше одного раза.',
'Найди ошибку: вместо SQUARE(i++) используйте функцию square, затем увеличьте i отдельным оператором. Ввод −100…100. Выведите квадрат исходного i и новое i.',
program('    int i;\n    if (scanf("%d", &i) != 1) return 1;\n    int result = square(i);\n    ++i;\n    printf("%d %d\\n", result, i);','static int square(int value) { return value * value; }'),
[('3','9 4\n'),('-2','4 -1\n'),('0','0 1\n')], 'Как гарантировать одно вычисление аргумента?','Использовать обычную функцию','Добавить ещё одну пару скобок в макрос')
add('conditional-compilation','Conditional compilation',
'''#if, #ifdef и #elif выбирают код при сборке. defined(NAME) отвечает, определён ли макрос, а #if NAME проверяет его числовое значение. Макрос, определённый как 0, всё ещё проходит #ifdef. Это различие особенно важно для флагов возможностей.

Задавайте значения по умолчанию через #ifndef, чтобы -D мог их переопределить. Неподдерживаемую комбинацию остановите через #error. Каждая поддерживаемая конфигурация — отдельная программа, которую нужно собрать и проверить: тесты только debug-ветки ничего не говорят о release-ветке. Избыточное число независимых флагов быстро увеличивает число комбинаций.''',
'Конфигурация сборки выбирает один чертёж; runtime if выбирает действие уже собранного устройства.',
'#ifdef FEATURE включает ветвь даже при -DFEATURE=0.',
'Задайте SENSOR_FAST=0 по умолчанию и выберите коэффициент 2 при #if SENSOR_FAST, иначе 1. В тестируемой конфигурации без внешних флагов ввод x −100…100 и вывод x.',
program('    int x;\n    if (scanf("%d", &x) != 1) return 1;\n    printf("%d\\n", x * gain);','#ifndef SENSOR_FAST\n#define SENSOR_FAST 0\n#endif\n#if SENSOR_FAST\nstatic const int gain = 2;\n#else\nstatic const int gain = 1;\n#endif'),
[('5','5\n'),('-9','-9\n'),('0','0\n')], 'Макрос FEATURE определён как 0. Что проверяет #ifdef FEATURE?','Наличие определения, поэтому ветвь включается','Числовой ноль, поэтому ветвь исключается')
add('static','static',
'''У static два важных применения. На уровне файла он даёт имени внутреннее связывание: другой объектный файл не обращается к нему как к внешнему символу. У локального объекта static задаёт статическую длительность хранения: объект существует всё выполнение, хотя имя доступно лишь внутри блока.

Локальный static инициализируется один раз, а не при каждом вызове. В C инициализатор такого объекта ограничен константными выражениями; это не произвольная динамическая инициализация C++. Скрытое изменяемое состояние усложняет повторный запуск теста и параллельные вызовы. Если нужно несколько независимых счётчиков, состояние лучше передать через struct, а не помещать в единственный static.''',
'Область видимости — где видно имя; длительность хранения — сколько живёт объект. Это разные координаты.',
'Локальный static не создаёт отдельную копию на каждый вызов и не делает ++ атомарным.',
'Функция next_id хранит static-счётчик и возвращает очередной номер с 1. Ввод n 0…20; выведите n номеров через пробел и перевод строки.',
program('    int n;\n    if (scanf("%d", &n) != 1 || n < 0 || n > 20) return 1;\n    for (int i=0; i<n; ++i) printf("%s%d", i ? " " : "", next_id());\n    puts("");','static int next_id(void) { static int value; return ++value; }'),
[('3','1 2 3\n'),('0','\n'),('1','1\n')], 'Что сохраняет локальный static между вызовами?','Состояние одного объекта','Отдельный новый объект каждого вызова')
add('extern','extern',
'''Объявление extern int total; сообщает тип и имя объекта, обычно определённого в другой единице трансляции. Само это объявление без инициализатора не предоставляет определение. В одном .c размещают int total = 0;, а заголовок подключают во все места использования.

Общее изменяемое состояние создаёт связь между модулями. Функции доступа часто лучше прямого extern: они позволяют сохранять инварианты и скрывать представление. Не путайте extern с выделением памяти или передачей значения. Инициализированное объявление extern int total = 0; уже является определением и не должно размножаться по заголовкам.''',
'extern — ссылка на общую ячейку по имени, а не ещё одна ячейка.',
'Добавление extern к инициализированной переменной в заголовке не устраняет повторные определения.',
'Объявите extern int total; и одно определение total=0. Прочитайте три значения −1000…1000, добавьте их функцией record и выведите total.',
program('    for (int i=0; i<3; ++i) { int x; if(scanf("%d", &x)!=1) return 1; record(x); }\n    printf("%d\\n", total);','extern int total;\nint total = 0;\nstatic void record(int value) { total += value; }'),
[('2 3 4','9\n'),('-5 5 0','0\n'),('1000 1000 1000','3000\n')], 'Где разместить определение общей переменной?','В одном .c, объявление — в заголовке','Во всех заголовках с инициализатором')
add('linkage','Linkage',
'''Связывание определяет, обозначают ли одинаковые имена один объект или функцию. Внешнее связывание объединяет подходящие объявления между единицами трансляции. Внутреннее ограничивает имя одной единицей. Локальные автоматические переменные не имеют связывания: одинаковое имя в двух функциях не объединяет их.

Линкер работает с символами, но совместимость типов — обязанность программы. Сообщение undefined reference обычно означает отсутствие нужного определения в переданных объектных файлах; multiple definition — конкурирующие определения. Не исправляйте их случайной сменой static: сначала решите, должно ли состояние быть общим. Файловый const в C по умолчанию не получает внутреннее связывание, в отличие от привычного правила C++.''',
'Связывание — правило идентичности имён; одинаковая надпись ещё не означает одну сущность.',
'Область видимости и linkage не взаимозаменяемы; файловый const в C не скрывает символ автоматически.',
'Скройте функцию clamp через static. Прочитайте x −1000…1000; верните 0 для отрицательных, 100 для больших 100 и x иначе.',
program('    int x;\n    if (scanf("%d", &x)!=1) return 1;\n    printf("%d\\n", clamp(x));','static int clamp(int x) { return x < 0 ? 0 : x > 100 ? 100 : x; }'),
[('-1','0\n'),('70','70\n'),('101','100\n')], 'Как скрыть файловую функцию от внешнего связывания?','Объявить static','Переименовать параметр')
add('const','const',
'''const ограничивает изменение через квалифицированное выражение. const int *p запрещает запись в int через p, но разрешает менять сам указатель; int *const p фиксирует указатель. Интерфейс чтения массива должен принимать const int *, чтобы компилятор обнаруживал случайную запись.

Квалификатор не делает память физически защищённой и не гарантирует константное выражение C17. Изменение объекта, определённого как const, через снявший квалификатор cast имеет неопределённое поведение. Если исходный объект изменяемый, другой допустимый указатель может его менять: const-view не означает, что значение никогда не меняется. Для дизайна API полезнее явно сформулировать, кто имеет право записи и как долго действителен указатель.''',
'const — разрешение на конкретном пути доступа, а не универсальная заморозка всех путей.',
'Приведение типа не делает законной запись в объект, который был определён const.',
'Напишите sum(const int *values, size_t count). Ввод n 0…20 и n целых −1000…1000. Выведите сумму без изменения массива.',
program('    int data[20]; size_t n;\n    if(scanf("%zu", &n)!=1 || n>20) return 1;\n    for(size_t i=0;i<n;++i) if(scanf("%d", &data[i])!=1) return 1;\n    printf("%d\\n", sum(data,n));','static int sum(const int *values, size_t count) { int result=0; for(size_t i=0;i<count;++i) result+=values[i]; return result; }'),
[('3 1 -2 5','4\n'),('0','0\n'),('1 -1000','-1000\n')], 'Что запрещает const int *p?','Изменение int через p','Присваивание другого адреса самому p')
add('volatile','volatile',
'''volatile сообщает реализации, что доступы к объекту имеют наблюдаемое значение, например при работе с отображённым аппаратным регистром. Конкретные гарантии ширины и порядка доступа определяются компилятором и платформой. Этот квалификатор не заменяет атомики и не обеспечивает межпоточную синхронизацию.

При чтении регистра значение может измениться между двумя доступами. Снимок в обычную переменную полезен, если дальнейший расчёт должен использовать одно наблюдение. Но чтение некоторых регистров само имеет побочный эффект, поэтому нельзя добавлять его «для удобства отладки» без документации устройства. В учебной программе volatile-объект находится в обычной памяти: это демонстрирует синтаксис, а не эмулирует реальное оборудование.''',
'Каждое чтение — отдельное наблюдение прибора; снимок хранит результат одного наблюдения.',
'volatile не устраняет data race и не превращает read-modify-write в атомарную операцию.',
'Прочитайте unsigned 0…255, присвойте volatile-объекту status. Снимите один снимок и выведите младший бит.',
program('    unsigned value;\n    if(scanf("%u", &value)!=1 || value>255) return 1;\n    volatile unsigned status = value;\n    unsigned snapshot = status;\n    printf("%u\\n", snapshot & 1u);'),
[('3','1\n'),('254','0\n'),('0','0\n')], 'Достаточно ли volatile для обмена данными между потоками?','Нет, нужны соответствующие средства синхронизации','Да, любые обращения становятся атомарными')
add('function-pointers','Function pointers',
'''Указатель на функцию содержит возможность вызвать функцию совместимого типа. В записи int (*operation)(int, int) скобки отделяют указатель от функции, возвращающей указатель. typedef может дать читаемое имя типу операции. Вызов допустим только при совместимости возвращаемого типа и параметров.

Таблица функций заменяет длинную цепочку выбора, когда обработчики имеют один контракт. Индекс таблицы всё равно нужно проверять, а NULL нельзя вызывать. Не храните указатели на функции в void * как переносимый C: гарантии преобразования объектных указателей не распространяются автоматически на функции. Хороший интерфейс фиксирует не только тип, но и допустимые диапазоны, эффекты и правила ошибок.''',
'Таблица диспетчеризации — набор одинаковых разъёмов с разными обработчиками.',
'Cast несовместимого указателя не исправляет несовместимость вызова.',
'Ввод: op (0 — сложение, 1 — разность), a и b от −1000 до 1000. Используйте таблицу указателей на функции и выведите результат.',
program('    int op,a,b;\n    if(scanf("%d%d%d",&op,&a,&b)!=3 || op<0 || op>1) return 1;\n    Operation operations[] = {add_values, subtract};\n    printf("%d\\n", operations[op](a,b));','typedef int (*Operation)(int,int);\nstatic int add_values(int a,int b){return a+b;}\nstatic int subtract(int a,int b){return a-b;}'),
[('0 2 4','6\n'),('1 2 4','-2\n'),('0 -10 10','0\n')], 'Какой тип должен иметь вызываемый обработчик?','Совместимый с типом указателя','Любой после явного cast')
add('callbacks','Callbacks',
'''Callback передаёт выбор действия вызывающему коду, а алгоритм сохраняет контроль над обходом. Контекст void * позволяет передать состояние без глобальных переменных. Контракт должен описывать, сколько раз вызывается обработчик, может ли он остановить обход и сохраняет ли алгоритм указатель на контекст после возврата.

Синхронный обход может использовать адрес локального контекста, пока вызов не завершился. Асинхронное хранение того же адреса требует более долгого времени жизни. Разделите данные и поведение: функция знает, что делать с одним элементом, структура контекста хранит сумму или порог. Это делает независимые экземпляры обработки возможными без скрытого static-состояния.''',
'Алгоритм задаёт маршрут, callback — действие на каждой остановке, context — переносимый блокнот.',
'Сохранение адреса локального контекста для будущего вызова создаёт dangling pointer.',
'Ввод n 0…20, порог t −1000…1000 и n значений того же диапазона. Через callback и контекст подсчитайте значения строго больше t.',
program('    int n; Context context={0,0};\n    if(scanf("%d%d", &n, &context.threshold)!=2 || n<0 || n>20) return 1;\n    void (*visit)(int,void*)=count_above;\n    for(int i=0;i<n;++i){int x;if(scanf("%d",&x)!=1)return 1;visit(x,&context);}\n    printf("%d\\n",context.count);','typedef struct { int threshold; int count; } Context;\nstatic void count_above(int x,void *opaque){Context *c=opaque;if(x>c->threshold)++c->count;}'),
[('4 5 4 5 6 9','2\n'),('0 0','0\n'),('3 -2 -3 -2 -1','1\n')], 'Кто отвечает за время жизни context?','Контракт и владелец переданного объекта','Сам тип void * автоматически продлевает жизнь')
add('void-pointer','void*',
'''void * переносит адрес объекта без информации о его конкретном типе. Преобразование объектного указателя в void * и обратно к исходному типу сохраняет возможность доступа. Для разыменования нужен подходящий тип, корректное выравнивание и живой объект. Арифметика void * не входит в стандарт C17; для обхода представления используют unsigned char *.

Универсальный API обычно передаёт вместе с адресом размер, количество элементов и функцию обработки. Потерянная типовая информация не исчезает из требований языка: её должен восстановить контракт. memcpy копирует представление между неперекрывающимися диапазонами, memmove допускает перекрытие. Они не проверяют, достаточно ли памяти выделено на принимающей стороне.''',
'Адрес без этикетки: прежде чем открыть коробку, восстановите размер, тип и владельца.',
'void * не означает «можно разыменовать как любой тип»; произвольный cast может нарушить alignment и aliasing.',
'Реализуйте swap_bytes(void *, void *, size_t) через unsigned char. Ввод два int −1000…1000; поменяйте их представления и выведите значения.',
program('    int a,b; if(scanf("%d%d",&a,&b)!=2)return 1;\n    swap_bytes(&a,&b,sizeof a);\n    printf("%d %d\\n",a,b);','static void swap_bytes(void *left,void *right,size_t count){unsigned char *a=left,*b=right;for(size_t i=0;i<count;++i){unsigned char t=a[i];a[i]=b[i];b[i]=t;}}'),
[('2 9','9 2\n'),('-5 0','0 -5\n'),('7 7','7 7\n')], 'Как обходить байты объекта в C17?','Через unsigned char *','Через арифметику void *')
add('bitwise-and','Bitwise AND',
'''Побитовое & оставляет единицу только там, где оба операнда имеют единицу. Поэтому value & mask выделяет выбранные признаки. Это не логическое &&: побитовая операция сохраняет набор разрядов, логическая даёт 0 или 1 и может не вычислить второй операнд.

Целочисленные продвижения происходят до операции, даже если исходное значение хранится в unsigned char. Для масок выбирайте беззнаковые типы и явно ограничивайте нужную ширину. Проверка наличия хотя бы одного бита выглядит как (value & mask) != 0, всех битов — (value & mask) == mask. При mask=0 вторая проверка истинна: пустой набор требований удовлетворён.''',
'Маска — трафарет: видим только отверстия, совпавшие с единицами данных.',
'Выражение value & mask == mask без скобок группируется не так, как обычно ожидают.',
'Ввод value и mask в диапазоне 0…255. Выведите value & mask.',
program('    unsigned value,mask;if(scanf("%u%u",&value,&mask)!=2)return 1;\n    printf("%u\\n",value & mask);'),
[('13 6','4\n'),('255 0','0\n'),('255 255','255\n')], 'Как проверить наличие всех требуемых битов?','(value & mask) == mask','value && mask')
add('bitwise-or','Bitwise OR',
'''Побитовое | устанавливает разряд, если он установлен хотя бы в одном операнде. Операция value | mask включает выбранные флаги, сохраняя остальные. Повторная установка той же маски не меняет результат: операция идемпотентна, что полезно для повторяемых команд настройки.

Это свойство относится к обычному числу, а не автоматически к аппаратному регистру: чтение или запись регистра может иметь специальные эффекты. В составном поле из нескольких битов OR недостаточно для замены значения, потому что старые единицы останутся. Сначала очистите маску поля через AND с инверсией, затем добавьте новое закодированное значение.''',
'OR включает переключатели, не трогая уже включённые соседние.',
'OR не заменяет многобитовое поле: старые единицы могут остаться.',
'Ввод value и enable 0…255. Включите биты enable и выведите новое значение.',
program('    unsigned value,enable;if(scanf("%u%u",&value,&enable)!=2)return 1;\n    printf("%u\\n",value | enable);'),
[('8 3','11\n'),('5 5','5\n'),('0 255','255\n')], 'Что даст повторная установка той же маски?','То же значение','Обязательно выключит биты')
add('xor','XOR',
'''Исключающее ИЛИ ^ устанавливает бит при различии соответствующих битов. XOR с маской переключает выбранные биты; повтор с той же маской возвращает исходное значение. XOR двух снимков состояния выделяет изменившиеся разряды, после чего AND с новым снимком выделяет включившиеся.

XOR всех байтов даёт простую контрольную сумму, но теряет информацию о порядке и не замечает многие парные изменения. Это не криптографическая защита и не замена CRC там, где важна надёжность обнаружения ошибок. XOR-swap хуже временной переменной для обычного обмена: он менее понятен и ошибочен при совпадении адресов.''',
'XOR — карта различий между двумя наборами битов.',
'В C оператор ^ не является возведением в степень.',
'Прочитайте старое и новое состояние 0…255; выведите маску изменившихся битов.',
program('    unsigned before,after;if(scanf("%u%u",&before,&after)!=2)return 1;\n    printf("%u\\n",before ^ after);'),
[('10 12','6\n'),('7 7','0\n'),('0 255','255\n')], 'Что показывает a ^ b?','Различающиеся разряды','Степень числа a')
add('bit-shifts','Bit shifts',
'''Сдвиг перемещает разряды, но допустимость зависит от продвинутого типа левого операнда и величины сдвига. Отрицательная величина или величина не меньше ширины типа даёт неопределённое поведение. Для битовых алгоритмов используйте unsigned: его левый сдвиг имеет модульную семантику при допустимой величине; правый заполняет старшие разряды нулями.

Для signed правила строже: левый сдвиг отрицательного числа недопустим, а правый сдвиг отрицательного в C17 определяется реализацией. Литерал 1 имеет тип int, поэтому маску удобнее начинать с 1u. Проверка индекса должна предшествовать сдвигу: проверять результат уже поздно.''',
'Сдвиг — движение в ленте фиксированной ширины; сначала проверьте размер ленты и шаг.',
'1 << 31 опасен для обычного 32-битного int; signed и unsigned нельзя считать взаимозаменяемыми.',
'Ввод k. Если k вне 0…7, выведите ОШИБКА. Иначе выведите 1u << k.',
program('    int k;if(scanf("%d",&k)!=1)return 1;\n    if(k<0 || k>7){puts("ОШИБКА");return 0;}\n    printf("%u\\n",1u << (unsigned)k);'),
[('3','8\n'),('7','128\n'),('8','ОШИБКА\n'),('-1','ОШИБКА\n')], 'Когда проверять величину сдвига?','До выполнения сдвига','После получения результата')
add('bit-masks','Bit masks',
'''Маска описывает расположение поля, а сдвиг — его позицию. Для чтения трёхбитового поля с позиции 2 вычисляют (value >> 2) & 7u. Для записи сначала очищают старое поле, затем добавляют новое: (value & ~(7u << 2)) | (field << 2). Значение field предварительно ограничивают диапазоном 0…7.

Разделите логическое значение поля и его закодированное представление. Функции encode/decode делают преобразование явным и удобным для тестов. Проверяйте, что соседние биты сохраняются, а записанное значение читается обратно. Не полагайтесь на порядок C bit-fields при описании переносимого протокола: явные маски дают контролируемый формат.''',
'Поле — ячейка в упакованном документе: удалить старые отметки, затем записать новые.',
'Если не очистить старые биты, запись меньшего значения может сохранить прежние единицы.',
'Ввод value 0…255 и field 0…7. Замените биты 2…4 новым field и выведите итог.',
program('    unsigned value,field;if(scanf("%u%u",&value,&field)!=2 || value>255 || field>7)return 1;\n    printf("%u\\n",(value & ~(7u << 2)) | (field << 2));'),
[('255 0','227\n'),('0 7','28\n'),('170 3','174\n')], 'Зачем очищать поле перед OR?','Чтобы удалить старые единицы','Чтобы изменить порядок байтов')
add('registers','Работа с регистрами',
'''Регистр устройства — интерфейс с аппаратной семантикой, а не просто unsigned по адресу. Документация определяет ширину доступа, зарезервированные биты, эффекты чтения и записи. У read-write регистра read-modify-write может быть допустим, но у write-one-to-clear запись единицы очищает флаг. Универсальное reg |= mask для такого регистра способно случайно сбросить другие события.

В учебной задаче моделируем W1C обычным числом, чтобы проверить логику без доступа к оборудованию. Реальный драйвер дополнительно зависит от ABI, memory barriers, платформенных функций MMIO и конкуренции с прерываниями. volatile само по себе не решает эти вопросы. Никогда не разыменовывайте придуманный аппаратный адрес в обычном приложении.''',
'Запись в регистр — команда устройству; значение команды не обязательно становится содержимым регистра.',
'Чтение всех флагов и обратная запись в W1C-регистр очищает все прочитанные единицы.',
'Модель W1C: ввод status и clear 0…255. Выведите status после очистки единиц маски clear: остальные флаги сохраняются.',
program('    unsigned status,clear;if(scanf("%u%u",&status,&clear)!=2)return 1;\n    printf("%u\\n",status & ~clear);'),
[('15 2','13\n'),('255 255','0\n'),('12 0','12\n')], 'Что означает единица при записи в W1C?','Очистить соответствующий флаг','Обязательно сохранить единицу')
add('binary-files','Binary files',
'''Бинарный формат задаёт байты, их порядок и смысл независимо от представления структур компилятора. Запись struct целиком переносит padding, размер типов и порядок байтов машины; такой файл не становится переносимым протоколом. Задайте сигнатуру, версию, длины и способ кодирования чисел явно.

Парсер проверяет доступность байтов до обращения и ограничивает количество записей до выделения памяти. Для little-endian значения из двух октетов формула b0 | (b1 << 8) работает после преобразования к достаточно широкому unsigned. В C байт не обязан быть восьмибитным; формат октетов требует CHAR_BIT == 8 или отдельной адаптации. Сначала проверяйте заголовок и длину, затем данные: частично разобранное сообщение не должно считаться успешным.''',
'Файл — договор о последовательности байтов, а не фотография struct в памяти.',
'fwrite(&record, sizeof record, 1, file) не определяет переносимый формат.',
'Ввод два десятичных октета lo и hi 0…255. Декодируйте little-endian unsigned 16-bit число без чтения через приведённый указатель.',
program('    unsigned lo,hi;if(scanf("%u%u",&lo,&hi)!=2 || lo>255 || hi>255)return 1;\n    printf("%u\\n",lo | (hi << 8));'),
[('52 18','4660\n'),('0 0','0\n'),('255 255','65535\n')], 'Что нужно фиксировать в формате?','Размеры полей и порядок байтов','Только имя C-структуры')
add('file-stream','FILE*',
'''FILE * — указатель на библиотечный поток, содержащий состояние буферизации, позицию и индикаторы конца/ошибки. Это не номер файлового дескриптора. fopen может вернуть NULL; каждый успешно открытый поток должен закрываться ровно один раз. Ошибка записи иногда обнаруживается только при fflush или fclose из-за буферизации.

Режим rb выбирает бинарное чтение, wb создаёт или обнуляет файл. tmpfile создаёт временный бинарный поток для чтения и записи, автоматически удаляемый после закрытия. При переходе от записи к чтению в update-потоке необходима предусмотренная стандартом операция синхронизации или позиционирования. В наших тестах используется fseek к началу, результат которого также проверяется.''',
'Поток — курсор плюс буфер и состояние; указатель является дескриптором владения этим ресурсом.',
'while (!feof(file)) проверяет прошлое состояние: конец становится известен после попытки чтения.',
'Прочитайте строку до 100 символов через fgets, запишите её в tmpfile, переместитесь к началу и сосчитайте байты до EOF, включая перевод строки, если он был во вводе. Выведите количество.',
program('    char text[102];if(!fgets(text,sizeof text,stdin))return 1;\n    FILE *file=tmpfile();if(!file)return 1;\n    if(fputs(text,file)==EOF || fseek(file,0,SEEK_SET)!=0){fclose(file);return 1;}\n    size_t count=0;while(fgetc(file)!=EOF)++count;\n    int failed=ferror(file);if(fclose(file)!=0)failed=1;\n    if(failed)return 1;printf("%zu\\n",count);'),
[('abc\n','4\n'),('\n','1\n'),('sensor','6\n')], 'Когда feof становится истинным?','После чтения, обнаружившего конец','Перед последним успешным чтением')
add('fread-fwrite','fread/fwrite',
'''fread и fwrite возвращают число полных элементов, а не всегда число байтов. Вызов fread(buf, 1, n, file) удобен для форматов: результат прямо показывает прочитанные байты. Короткое чтение требует проверки ferror и feof; частичный элемент не следует трактовать как полноценную запись.

Выделите функцию чтения точного количества байтов, которая возвращает статус и не выдаёт частичные данные за успех. После полного разбора проверьте политику лишнего хвоста: запрещён он или содержит следующий пакет. Для записи необходимо проверять и количество элементов, и завершение буферизованного вывода. В проекте бинарного парсера эти проверки отделяют корректный пустой файл формата от обрезанного заголовка.''',
'Чтение — запрос на порцию, а возвращаемое число — подтверждение реально полученного объёма.',
'Успешное чтение одного байта заголовка не означает, что весь заголовок доступен.',
'Ввод n 0…20 и n байтов 0…255. Запишите массив в tmpfile через fwrite с размером элемента 1, прочитайте через fread и выведите сумму байтов.',
program('    size_t n;if(scanf("%zu",&n)!=1 || n>20)return 1;\n    unsigned char data[20];for(size_t i=0;i<n;++i){unsigned x;if(scanf("%u",&x)!=1 || x>255)return 1;data[i]=(unsigned char)x;}\n    FILE *f=tmpfile();if(!f)return 1;\n    if(fwrite(data,1,n,f)!=n || fseek(f,0,SEEK_SET)!=0){fclose(f);return 1;}\n    unsigned char copy[20];if(fread(copy,1,n,f)!=n){fclose(f);return 1;}\n    if(fclose(f)!=0)return 1;\n    unsigned sum=0;for(size_t i=0;i<n;++i)sum+=copy[i];printf("%u\\n",sum);'),
[('3 1 2 255','258\n'),('0','0\n'),('1 0','0\n')], 'Что возвращает fread(buf, 4, 3, f)?','Число полных четырёхбайтовых элементов','Всегда число прочитанных байтов')
add('error-handling','Error handling в C',
'''В C ошибки обычно представлены статусом возврата и отдельным выходным параметром. Успешное значение не должно пересекаться с кодом ошибки. Хороший контракт определяет, изменяется ли выходной параметр при отказе и кто освобождает ресурсы. Это позволяет вызывающему коду безопасно повторить операцию или откатиться.

Сосредоточьте освобождение ресурсов в понятных ветвях или одном блоке cleanup. goto cleanup может упростить проверку нескольких ресурсов, если переходы направлены только к освобождению. Не заменяйте проверку ввода assert: пользовательская ошибка — штатный сценарий. В анализаторе строка с неверными данными учитывается как ошибка данных, а отказ чтения файла прекращает обработку; это разные уровни отказа.''',
'Функция возвращает два канала: статус операции и данные, действительные только при успехе.',
'Ноль бывает корректным результатом; его нельзя одновременно использовать как единственный признак ошибки.',
'Реализуйте divide(a,b,out): при b=0 ошибка и out не меняется. Ввод a,b −1000…1000; выведите целочисленное частное либо ОШИБКА.',
program('    int a,b,result=0;if(scanf("%d%d",&a,&b)!=2)return 1;\n    if(divide(a,b,&result)!=0)puts("ОШИБКА");else printf("%d\\n",result);','static int divide(int a,int b,int *out){if(b==0)return -1;*out=a/b;return 0;}'),
[('9 2','4\n'),('0 2','0\n'),('1 0','ОШИБКА\n'),('-9 2','-4\n')], 'Когда читать выходной параметр функции?','После проверки успешного статуса','Всегда, независимо от контракта')
add('errno','errno',
'''errno — изменяемый индикатор ошибки, который имеет смысл только согласно контракту вызванной функции. Успешная функция не обязана обнулять старое значение. Поэтому для strtol перед вызовом устанавливают errno=0, после проверяют ERANGE, указатель конца и наличие хотя бы одной цифры.

Проверка end==start отличает отсутствие числа от корректного нуля, а остаток строки — частично разобранный токен от полного. Затем отдельно проверяется диапазон прикладной задачи. Не сравнивайте errno с придуманными числовыми константами: используйте имена из errno.h. Если последующие вызовы могут изменить errno, сохраните его сразу после обнаружения ошибки.''',
'errno — записка о конкретном неудачном вызове, а не общий датчик исправности программы.',
'Проверка только результата strtol не различает корректный ноль и отсутствие числа.',
'Ввод один токен до 100 символов. Разберите его strtol в десятичной системе. При лишних символах, переполнении или значении вне −1000…1000 выведите ОШИБКА; иначе число.',
program('    char text[101],*end; if(scanf("%100s",text)!=1)return 1;\n    errno=0;long value=strtol(text,&end,10);\n    if(errno==ERANGE || end==text || *end!=\'\\0\' || value < -1000 || value > 1000)puts("ОШИБКА");\n    else printf("%ld\\n",value);','#include <stdlib.h>\n#include <errno.h>'),
[('-32','-32\n'),('12x','ОШИБКА\n'),('0','0\n'),('99999999999999999999999999999','ОШИБКА\n')], 'Почему errno обнуляют перед strtol?','Чтобы отличить новую ошибку от старого значения','Потому что успешный strtol всегда оставляет ERANGE')
add('assertions','Assertions',
'''assert проверяет внутреннее утверждение программы и аварийно завершает её при нарушении в сборке с активными проверками. При определённом NDEBUG выражение не вычисляется. Поэтому обязательные операции, ввод и изменение состояния нельзя прятать в assert.

Проверки внешнего ввода остаются обычным кодом во всех конфигурациях. Утверждения документируют уже установленные инварианты, например size <= capacity после успешного reserve. Если их нарушение возможно из-за обычного пользовательского ввода, это признак неверно выбранного уровня проверки. _Static_assert выполняется при трансляции и полезен для предположений о целевой платформе, а не для runtime-данных.''',
'assert — сигнал о нарушении доказанного внутреннего правила; проверка ввода — часть нормального поведения.',
'assert(scanf(...) == 1) удалит чтение ввода при NDEBUG.',
'Прочитайте n. При n вне 0…20 выведите ОШИБКА обычной проверкой; иначе assert подтвердит инвариант, затем выведите n*n.',
program('    int n;if(scanf("%d",&n)!=1)return 1;\n    if(n<0 || n>20){puts("ОШИБКА");return 0;}\n    assert(n>=0 && n<=20);printf("%d\\n",n*n);','#include <assert.h>'),
[('4','16\n'),('20','400\n'),('-1','ОШИБКА\n')], 'Что происходит с выражением assert при NDEBUG?','Оно не вычисляется','Оно всегда выполняется, но молча')
add('makefile','Makefile',
'''Make описывает граф: цель, зависимости и рецепт обновления. Если зависимость новее цели или цель отсутствует, рецепт выполняется. Заголовки тоже влияют на объектные файлы: забытая зависимость даёт устаревшую сборку. Флаги -MMD -MP помогают компилятору создавать зависимости для включённых пользовательских заголовков.

Команды рецепта начинаются табуляцией. .PHONY помечает действия, не соответствующие обычному файлу, например clean и test. Разделяйте компиляцию .c в .o и линковку, передавайте нужные флаги на соответствующий этап. Чистая сборка должна воспроизводить результат инкрементальной: если после удаления build поведение меняется, граф зависимостей неполон.''',
'Make — план ремонта: обновить узлы, чьи входные материалы изменились.',
'Зависимость только от .c пропускает изменения интерфейса в .h.',
'Учебная модель графа: ввод время object и время source (0…10000). Выведите ПЕРЕСОБРАТЬ, если source новее object, иначе ГОТОВО. Затем примените реальный Makefile из теории к программе.',
program('    unsigned object,source;if(scanf("%u%u",&object,&source)!=2)return 1;\n    puts(source>object ? "ПЕРЕСОБРАТЬ" : "ГОТОВО");'),
[('10 11','ПЕРЕСОБРАТЬ\n'),('10 10','ГОТОВО\n'),('20 1','ГОТОВО\n')], 'Зачем .PHONY: clean?','Чтобы имя файла clean не подавляло действие','Чтобы удалить зависимости заголовков')
add('cmake','CMake',
'''CMake описывает цели и их требования, затем генерирует сборочную систему. cmake -S . -B build выполняет конфигурацию, cmake --build build запускает сборку. Каталог build хранит кэш и артефакты отдельно от исходников. Файлы генератора не редактируют вручную: изменение задают в CMakeLists.txt.

Назначайте include-пути, определения и параметры конкретным targets. PUBLIC нужен потребителям и самой цели, PRIVATE — только реализации, INTERFACE — только потребителям. Для C17 требуйте стандарт и отключайте расширения, если нужна переносимость. CTest запускает зарегистрированные тесты, но не придумывает проверки автоматически: test executable должен возвращать ненулевой код при нарушении ожиданий.''',
'CMake формирует правила сборки для целей, а выбранный backend исполняет их.',
'Конфигурация CMake ещё не означает, что бинарный файл собран или тесты выполнены.',
'Напишите чистую функцию bounded(x) для диапазона 0…255. Ввод x −1000…1000; вывод 1 при попадании и 0 иначе. В инструкции CTest используйте отдельный тест этой функции.',
program('    int x;if(scanf("%d",&x)!=1)return 1;printf("%d\\n",bounded(x));','static int bounded(int x){return x>=0 && x<=255;}'),
[('255','1\n'),('-1','0\n'),('256','0\n')], 'Что делает cmake --build build?','Запускает сгенерированную сборку','Только печатает исходный CMakeLists.txt')
add('gdb','GDB',
'''Отладчик связывает машинное состояние с исходником через отладочную информацию. Соберите с -g и умеренной оптимизацией, например -Og для GCC. break останавливает перед нужным участком, next выполняет строку без входа в вызов, step входит, backtrace показывает цепочку вызовов. Watchpoint полезен, когда известно повреждённое значение, но неизвестен писатель.

Сначала сформулируйте гипотезу и минимальный воспроизводимый ввод. Сравните ожидаемый инвариант с переменными на остановке. Значение может быть optimized out, а строка соответствовать нескольким инструкциям: исходный текст не является точной временной шкалой оптимизированного бинарника. После исправления добавьте автоматический регрессионный тест, иначе знание останется только в сеансе отладки.''',
'Отладчик — остановка времени с осмотром состояния; тест — повторяемое доказательство найденного сценария.',
'Смена случайных переменных в debugger без гипотезы может скрыть причину, а не исправить её.',
'Найди ошибку в накоплении: сумма должна начинаться с 0. Ввод n 0…20 и n чисел −1000…1000. Выведите сумму; пустой набор даёт 0.',
program('    int n,sum=0;if(scanf("%d",&n)!=1 || n<0 || n>20)return 1;\n    for(int i=0;i<n;++i){int value;if(scanf("%d",&value)!=1)return 1;sum+=value;}\n    printf("%d\\n",sum);'),
[('3 2 -1 4','5\n'),('0','0\n'),('1 -3','-3\n')], 'Что поможет найти неожиданную запись в переменную?','Watchpoint','Удаление отладочной информации')
add('lldb','LLDB',
'''LLDB тоже использует отладочную информацию, но имеет свой язык команд. breakpoint set --name main задаёт точку останова, run запускает программу, frame variable показывает локальные значения, thread backtrace — стек. Команды чтения памяти требуют понимания размера и формата; интерпретация случайных байтов как указателя не делает его допустимым.

Отладочная стратегия переносится между GDB и LLDB: минимальный ввод, гипотеза, остановка перед нарушением, проверка границ и времени жизни. Сравнивайте не только финальное значение, но и первый момент расхождения. Для ошибки индекса полезно следить за i и count перед доступом. В браузере интерактивный debugger не запускается: ниже даны команды для отдельной доверенной учебной среды.''',
'Команды меняются, но расследование остаётся тем же: где впервые нарушен инвариант?',
'Условие i <= count обращается к элементу за логическим концом массива.',
'Исправьте границу обхода: ввод n 1…20 и n целых −1000…1000. Выведите максимум, начиная с первого элемента, а не с нуля.',
program('    int n,data[20];if(scanf("%d",&n)!=1 || n<1 || n>20)return 1;\n    for(int i=0;i<n;++i)if(scanf("%d",&data[i])!=1)return 1;\n    int maximum=data[0];for(int i=1;i<n;++i)if(data[i]>maximum)maximum=data[i];\n    printf("%d\\n",maximum);'),
[('3 -5 -2 -9','-2\n'),('1 0','0\n'),('4 1 8 3 2','8\n')], 'Почему максимум не стоит инициализировать нулём?','Все значения могут быть отрицательными','Ноль нельзя хранить в int')
add('sanitizers','Sanitizers',
'''Санитайзеры инструментируют программу, добавляя проверки во время выполнения. ASan обнаруживает многие выходы за границы и обращения после освобождения; UBSan — ряд нарушений правил языка, включая знаковое переполнение. Нужные флаги должны участвовать и в компиляции, и в линковке. Диагностическая сборка дополняет функциональную, а не заменяет её.

Отсутствие сообщения не доказывает корректность всех путей. Логическая ошибка внутри выделенного диапазона может остаться незамеченной, поэтому нужны ожидаемые результаты и граничные тесты. Сначала читайте первое сообщение и стек причины, затем вторичные симптомы. Не подавляйте сообщение изменением тайминга или отключением проверки: восстановите правильное владение и границы. В платформе режим диагностики выбирается сервером, ученик не может отменить его запросом.''',
'Санитайзер — датчик нарушения на выполненном пути; тест выбирает путь и проверяет смысл результата.',
'Чистый ASan не доказывает отсутствие всех ошибок, особенно неисполненных ветвей.',
'Найди ошибку: выделите n int, а не n байтов, и обходите i<n. Ввод n 0…20 и n чисел −1000…1000. Выведите сумму, освободив массив; n=0 обработайте без выделения.',
program('    size_t n;if(scanf("%zu",&n)!=1 || n>20)return 1;\n    if(n==0){puts("0");return 0;}\n    int *data=malloc(n*sizeof *data);if(!data)return 1;\n    int sum=0;for(size_t i=0;i<n;++i){if(scanf("%d",&data[i])!=1){free(data);return 1;}sum+=data[i];}\n    free(data);printf("%d\\n",sum);','#include <stdlib.h>'),
[('3 4 5 6','15\n'),('0','0\n'),('1 -5','-5\n')], 'Доказывает ли чистый прогон отсутствие ошибок на всех входах?','Нет, проверены только выполненные пути','Да, санитайзер перебирает все программы')
